module.exports = {
  init (projectName, testProfilesConfigFilepath, testServiceUser, testServiceAccessKey, webdriverUri, localTestUrl, testDebug) {

    // Helper: parse address
    function _getHostAddress (uri, defaultHost, defaultPort) {
      const addr = {};

      if (uri === undefined) { // If no uri, use default
        addr.protocol = 'http://';
        addr.port = defaultPort;
        addr.host = defaultHost;
      } else { // Otherwise parse provided uri
        const uriSplit = uri.replace(/http:\/\/|https:\/\//, '').split(':', 2);

        addr.protocol = (uri.toLowerCase().indexOf('https') == 0 ? 'https://' : 'http://');

        if (uriSplit.length == 0) {
          throw new Error('Invalid webdriveruri specified:' + uri);
        } else if (uriSplit.length < 2) {
          addr.port = defaultPort;
        } else {
          addr.port = uriSplit[1];
        }
        addr.host = uriSplit[0];
      }
      return addr.protocol + addr.host + ':' + addr.port;
    }

    // Setting up default test environment configuration supporting both Browserstack and SauceLabs parameters
    let defaultSettings = {
      'browserstack.user': testServiceUser,
      'browserstack.key': testServiceAccessKey,
      'browserstack.local': (localTestUrl === undefined ? false : localTestUrl),
      'browserstack.debug': (testDebug === undefined ? true : testDebug),
      username: testServiceUser,
      accessKey: testServiceAccessKey,
      webdriveruri: _getHostAddress(webdriverUri, 'localhost', 8001),
      name: projectName + ' unit tests',
      project: projectName + ' unit tests',
      logType: false
    };

    if (process.env.TRAVIS) {
      defaultSettings.tunnelIdentifier = process.env.TRAVIS_JOB_NUMBER;
    }

    // Loading requested test profiles
    testEnvironments = require(testProfilesConfigFilepath);

    // Add some required settings from vendor specific test service
    defaultSettings.serverurl = testEnvironments.serverurl;

    // Add default profile
    testEnvironments.default = testEnvironments.phantomjs = {
      browserName: 'phantomjs',
      serverurl: defaultSettings.webdriveruri,
      logType: 'browser',
      desc: 'Phantomjs via webdriver on ' + defaultSettings.webdriveruri
    };

    // Adding default config data if not specified for test environments
    for (const testenv in testEnvironments) {
      for (const defaultProp in defaultSettings) {
        // Only for instances that are not URLs, nor phantomjs instances.
        if (typeof testEnvironments[testenv] === 'object' && testEnvironments[testenv][defaultProp] === undefined) {
          testEnvironments[testenv][defaultProp] = defaultSettings[defaultProp];
        }
      }
    }

    return this;
  },

  // Get all test profiles
  getTestProfileList (showRemoteProfilesOnly) {
    let results = [];
    const filterlocalProfiles = (showRemoteProfilesOnly !== undefined && showRemoteProfilesOnly !== false ? true : false)
      , localProfilesToIgnore = [undefined, 'phantomjs', 'default'];

    for (const testenv in testEnvironments) {
      const testProfile = testEnvironments[testenv]
        , testProfileName = (testProfile.browserName === undefined ? testProfile.browser : testProfile.browserName);

      if (filterlocalProfiles === false || filterlocalProfiles === true && localProfilesToIgnore.indexOf(testProfileName) == -1) {
        testProfile.description = 'Testprofile ' + testenv;
        results.push(testProfile);
      }
    }
    return results;
  },

